# Detect text appearing inside an image using Azure AI Vision\nimport os\n\n# Azure SDK for image OCR\nfrom azure.ai.vision import VisionClient\nfrom azure.core.credentials import AzureKeyCredential\n\nclass DetectImageText:\n    \"\"\"Extract printed or handwritten text from an image.\n    \"\"\"\n    @staticmethod\n    def extract_text(image_path: str) -> list:\n        \"\"\"Run OCR on the supplied image.\n        Args:\n            image_path (str): Path to the image file.\n        Returns:\n            list: List of recognized lines, each containing text and bounding box.\n        \"\"\"\n        # Configuration is read from environment variables (AZURE_VISION_ENDPOINT, AZURE_VISION_KEY)\n        vision_client = VisionClient(credential=AzureKeyCredential(os.getenv(\"AZURE_VISION_KEY\")),\n                                      endpoint=os.getenv(\"AZURE_VISION_ENDPOINT\"))\n        # Use the built‑in OCR model (azure-ai-vision-imageanalysis)\n        result = vision_client.read(image=os.path.abspath(image_path))\n        # Normalize results to a simple list of (text, bbox) tuples\n        text_lines = []\n        for region in result.regions:\n            for line in region.lines:\n                bbox = (line.bounding_box.left, line.bounding_box.top,\n                        line.bounding_box.width, line.bounding_box.height)\n                text_lines.append((line.text, bbox))\n        return text_lines\n\n# Local helper utilities (loaded in VisionClient)\n# -----------------------------------------------------------------------------\n# Configuration loading and client helpers defined in vision_client.py (separate file)\n# -----------------------------------------------------------------------------
